	public void SpawnDefeatedVFX(Vector3 position, GameObject defeatedVFXPrefab, GameObject corruptedSentinelDefeatedVFXPrefab)
	{
		if (!ReferenceSingleton<VFXHandler>.Instance.IsVFXEnabled())
		{
			return;
		}
		GameObject vfxPrefab = null;
		if (defeatedVFXType == DefeatedVFXType.NONE)
		{
			return;
		}
		if (defeatedVFXType == DefeatedVFXType.NORMAL || defeatedVFXType == DefeatedVFXType.BOSS)
		{
			ReferenceSingleton<VFXHandler>.Instance.GetVFX(defeatedVFXPrefab, position, 10f).GetComponent<EnemyDefeatedVFX>().Initialize(defeatedVFXType == DefeatedVFXType.BOSS);
			return;
		}
		if (IsDefeatedVFXSentinel)
		{
			vfxPrefab = corruptedSentinelDefeatedVFXPrefab;
		}
		else if (isDefeatedVFXCustom)
		{
			vfxPrefab = defeatedVFX;
		}
		ReferenceSingleton<VFXHandler>.Instance.GetVFX(vfxPrefab, position, 10f);
	}

	public void SpawnActivationVFX(Vector3 position)
	{
		SpawnVFX(position, enableActivationVFX, enableActivationVFXDelay, activationVFXDelay, activationVFX);
	}

	private void SpawnVFX(Vector3 position, bool enableVFXBool, bool enableVFXDelayBool, float vfxDelay, GameObject vfxPrefab)
	{
		if (!enableVFXBool || !ReferenceSingleton<VFXHandler>.Instance.IsVFXEnabled())
		{
			return;
		}
		if (enableVFXDelayBool)
		{
			InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, vfxDelay, delegate
			{
				SpawnVFX();
			});
		}
		else
		{
			SpawnVFX();
		}
		void SpawnVFX()
		{
			ReferenceSingleton<VFXHandler>.Instance.GetVFX(vfxPrefab, position, 10f);
		}
	}

	public void CheckActivationScreenshake(FloatFloatEvent OnScreenShake)
	{
		if (!enableActivationScreenshake)
		{
			return;
		}
		if (enableActivationScreenshakeDelay)
		{
			InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, activationScreenshakeDelay, delegate
			{
				PlayScreenshake(OnScreenShake);
			});
		}
		else
		{
			PlayScreenshake(OnScreenShake);
		}
	}

	private void PlayScreenshake(FloatFloatEvent OnScreenShake)
	{
		if (enableActivationScreenshakeCustomPowerAndDuration)
		{
			OnScreenShake.Raise(activationScreenshakeCustomPower, activationScreenshakeCustomDuration);
		}
		else
		{
			OnScreenShake.Raise(0.1f, 0.3f);
		}
	}
